const ok = {id:"123e4567-e89b-12d3-a456-426614174000", email:"a@b.com", name:"n", ip:"1.2.3.4", plan:"free", flags:{}};
const S = (o)=>JSON.stringify(o);
print("== raw zod3 .ip() behaviour ==");
for (const s of ["fe80::1%eth0","5ac3::de2a%wlan0","::%1","2001:db8::ff00:42:8329%25","fe80::1","1.2.3.4"]) {
  let r3, r3v6;
  try { r3 = zod3.string().ip().safeParse(s).success; } catch(e){ r3 = "ERR:"+e.message; }
  try { r3v6 = zod3.string().ip({version:"v6"}).safeParse(s).success; } catch(e){ r3v6 = "ERR"; }
  print("  ", s, "zod3.ip()=", r3, " zod3.ip(v6)=", r3v6);
}
print("== signup ip via oracle vs main ==");
for (const ip of ["fe80::1%eth0","5ac3::de2a%wlan0","::%1","7e60::16eb%25","1.2.3.4","fe80::1","notanip","1.2.3.4%eth0","::1%","%eth0"]) {
  const inp = Object.assign({}, ok, {ip});
  const a = oracle.parseSignup(inp), b = main.parseSignup(inp);
  print("  ", JSON.stringify(ip), "oracle=", a.ok ? "ACCEPT" : "reject "+S(a.problems), " main=", b.ok ? "ACCEPT" : "reject "+S(b.problems));
}
print("== config timeoutMs / hosts ==");
for (const t of [Infinity, -Infinity, NaN, 5000, 0, -1]) {
  const inp = {port:"8080", hosts:["1.2.3.4"], timeoutMs:t};
  const a = oracle.parseConfig(inp), b = main.parseConfig(inp);
  print("  timeoutMs=", String(t), "oracle=", a.ok ? "ACCEPT "+S(a.value) : "reject "+S(a.problems), " main=", b.ok ? "ACCEPT "+S(b.value) : "reject "+S(b.problems));
}
const h = {port:"8080", hosts:["2459::52d2%lo0"], timeoutMs:5000};
print("  hosts zoned: oracle=", S(oracle.parseConfig(h)), " main=", S(main.parseConfig(h)));
print("== age ==");
for (const age of [1e21, 9007199254740994, 42, 12, 9007199254740991]) {
  const inp = Object.assign({}, ok, {age});
  const a = oracle.parseSignup(inp), b = main.parseSignup(inp);
  print("  age=", String(age), "oracle=", a.ok?"ACCEPT":"reject", " main=", b.ok?"ACCEPT":"reject "+S(b.problems));
}
print("== website value normalisation ==");
for (const w of [" https://example.com","https://example.com\n","https://example.com","https://EXAMPLE.com/A B","https://example.com/a/../b","http://example.com?x=1","  https://example.com/path  "]) {
  const inp = Object.assign({}, ok, {website:w});
  const a = oracle.parseSignup(inp), b = main.parseSignup(inp);
  print("  in=", JSON.stringify(w), "oracle=", a.ok?JSON.stringify(a.value.website):"reject", " main=", b.ok?JSON.stringify(b.value.website):"reject");
}

function z3ip(s){ try { return zod3.string().ip().safeParse(s).success } catch(e) { return 'ERR:'+e.message } }
const base = {id:"123e4567-e89b-12d3-a456-426614174000", email:"a@b.com", name:"n", ip:"1.2.3.4", plan:"free", flags:{}};
function sip(s){ const r = main.parseSignup(Object.assign({}, base, {ip:s})); return r.ok ? 'ACCEPT '+JSON.stringify(r.value.ip) : 'reject '+JSON.stringify(r.problems); }
function oip(s){ const r = oracle.parseSignup(Object.assign({}, base, {ip:s})); return r.ok ? 'ACCEPT '+JSON.stringify(r.value.ip) : 'reject'; }
print('== which zoned forms did zod3 .ip() accept? ==');
for (const s of ["fe80::1%eth0","fe80::2%eth0","fe80::1%wlan0","fe80::1%25","FE80::1%eth0","fe81::1%eth0","fe80:0:0:0:0:0:0:1%eth0","2001:db8::1%eth0","::%1","5ac3::de2a%wlan0"]) print('  ', JSON.stringify(s), 'zod3=', z3ip(s), 'oracle=', oip(s), 'main=', sip(s));
print('== how permissive is the new zone branch? ==');
for (const s of ["fe80::1%", "fe80::1%eth0%x", "fe80::1% ", "fe80::1%'; DROP TABLE users--", "fe80::1%<script>alert(1)</script>", "fe80::1%"+"a".repeat(300), "fe80::1%../../etc/passwd", "fe80::1%\n", "notanip%eth0", "1.2.3.4%eth0"]) print('  ', JSON.stringify(s), 'zod3=', z3ip(s), 'main=', sip(s));
print('== website: does trimming ever flip a verdict? ==');
for (const w of [" https://example.com", "https://example.com\n", "\thttps://example.com ", "https:// example.com", " ", "https://exa mple.com", "  not a url  "]) {
  const a = oracle.parseSignup(Object.assign({}, base, {website:w}));
  const b = main.parseSignup(Object.assign({}, base, {website:w}));
  print('  ', JSON.stringify(w), 'oracle=', a.ok?JSON.stringify(a.value.website):'reject', 'main=', b.ok?JSON.stringify(b.value.website):'reject');
}
print('== can Infinity/huge come from JSON? ==');
print('  JSON.stringify(Infinity) =', JSON.stringify(Infinity));
print('  JSON.parse("1e999") =', JSON.parse('1e999'));
const cfg = (t) => { const r = main.parseConfig({hosts:["1.2.3.4"], timeoutMs:t}); return r.ok?'ACCEPT':'reject '+JSON.stringify(r.problems); };
print('  main timeoutMs 1e999 =', cfg(JSON.parse('1e999')), ' 1e21 =', cfg(1e21));
const ocfg = (t) => { const r = oracle.parseConfig({hosts:["1.2.3.4"], timeoutMs:t}); return r.ok?'ACCEPT':'reject'; };
print('  oracle timeoutMs 1e999 =', ocfg(JSON.parse('1e999')), ' 1e21 =', ocfg(1e21));

